export function createStatements(a){
  const {esc,money,fullDate,icon,btn,link}=a;
  const archived=()=>(a.state.archivedTransactions||[]).filter(t=>t.company===a.company);
  const findTransaction=id=>a.scope('transactions').find(t=>t.id===id)||archived().find(t=>t.id===id);
  function summary(){
    const accounts=a.scope('accounts').filter(x=>x.statement),dataset=a.state.dataset||{};
    if(!accounts.length)return {heading:'Extratos utilizados',body:'<h2>Nenhum extrato incluído</h2><p>Esta versão começa vazia. Documentos, contas e lançamentos reais não fazem parte do código público.</p>'};
    return {heading:'Extratos utilizados',wide:true,body:`<h2>Histórico importado</h2><p class="description">${accounts.reduce((n,x)=>n+x.statement.transactionCount,0)} movimentos ativos. Valores e continuidade de saldos conferidos; classificação contábil e conciliação documental continuam separadas.</p><div class="callout">${icon('info')}<span>${esc(dataset.balanceNote||'Consulte a base de saldo de cada banco.')} ${dataset.missing?.length?'Há períodos sem cobertura; consulte as fontes de cada conta.':''}</span></div><div class="table-wrap"><table><thead><tr><th>Banco / cobertura</th><th>Movimentos</th><th>Saldo inicial</th><th>Créditos</th><th>Débitos</th><th>Saldo final</th></tr></thead><tbody>${accounts.map(x=>`<tr><td>${esc(x.name)}<small>${fullDate(x.statement.period.start)} — ${fullDate(x.statement.period.end)}</small><small>${x.statement.balanceBasis==='consolidated'?'Com aplicação automática incorporada':'Conta corrente'}</small></td><td>${x.statement.transactionCount}</td><td>${money(x.opening)}</td><td>${money(x.statement.incoming)}</td><td>${money(x.statement.outgoing)}</td><td>${money(x.statement.closing)}</td></tr>`).join('')}</tbody></table></div>${accounts.map(x=>{
      const s=x.statement,sources=s.sources||[{document:s.document,name:s.source.name,period:s.period}],snap=s.emissionSnapshot;
      return `<div class="drawer-section"><h3>${esc(x.name)}</h3>${sources.map(source=>link(`${fullDate(source.period.start)} — ${fullDate(source.period.end)}`,'document',source.document,source.name,'file')).join('')}<p class="annotation">${esc((s.excludedSections||[]).join('; '))}.</p>${s.balanceAnchor?`<p class="annotation">A data de saldo dos OFX é a data da exportação. Os saldos históricos foram calculados pelos movimentos e conferidos com o saldo de ${fullDate(s.balanceAnchor.date)} do PDF anterior (${money(s.balanceAnchor.amount)}).</p>`:''}${snap?`<details><summary>Resumo da emissão e diferença de saldo</summary><p>Em ${fullDate(snap.date)}, o cabeçalho informa disponível de ${money(snap.available)}, outras aplicações de ${money(snap.otherInvestments)} e total de ${money(snap.total)}. A tabela de movimentos encerra em ${money(s.closing)}: diferença de ${money(snap.available-s.closing)} em relação ao disponível. O gráfico usa a tabela, sem ajuste inventado; as outras aplicações não foram extrapoladas para datas anteriores.</p></details>`:''}${s.investments.length?`<details><summary>${s.investments.length} observações auxiliares do Invest Fácil</summary><p class="annotation">São posições nas datas informadas, com lacunas no histórico. ${s.balanceBasis==='consolidated'?'Não são somadas novamente ao saldo consolidado do Bradesco.':'Permanecem separadas dos movimentos de conta corrente.'}</p><div class="table-wrap"><table><thead><tr><th>Data</th><th>Invest Fácil</th><th>Fonte</th></tr></thead><tbody>${s.investments.map(p=>`<tr><td>${fullDate(p.date)}</td><td>${money(p.amount)}</td><td>${btn('Página '+p.sourcePage,`data-statement-document="${esc(p.sourceDocument||s.document)}" data-source-page="${p.sourcePage}"`,'','file')}</td></tr>`).join('')}</tbody></table></div></details>`:'<p class="annotation">Os movimentos de BB Rende Fácil não informam o saldo total da aplicação. Falta o extrato de investimentos para completar este banco.</p>'}</div>`;
    }).join('')}${dataset.duplicateFiles?.length?`<p class="statement-coverage">${dataset.duplicateFiles.length} arquivo repetido ignorado: ${dataset.duplicateFiles.map(d=>esc(d.file)+' é idêntico a '+esc(d.sameAs)).join('; ')}. Arquivos duplicados não acrescentam movimentos.</p>`:''}${archived().length?`<details><summary>${archived().length} aplicações/resgates do extrato anterior · consulta</summary><p>O extrato antigo separava conta corrente e Invest Fácil. Estes registros permanecem acessíveis com seus vínculos, fora das somas do novo extrato consolidado.</p>${archived().map(t=>link(`${fullDate(t.date)} · ${money(t.amount)}`,'transaction',t.id,t.description,'wallet')).join('')}</details>`:''}<div class="callout">${icon('info')}<span>Créditos não equivalem automaticamente a receitas, nem débitos a despesas. Obrigações, contratos, ativos, rateios e comprovantes ainda precisam ser relacionados.</span></div>`};
  }
  function transaction(id){
    const t=findTransaction(id);if(!t)return {heading:'Lançamento',body:'Lançamento indisponível.'};
    const account=a.get('accounts',t.account),doc=a.get('documents',t.sourceDocument),o=a.get('obligations',t.obligation),ofx=doc?.format==='ofx';
    return {heading:'Lançamento bancário',body:`<h2>${esc(t.history||t.description)}</h2><p class="description">${fullDate(t.date)} · ${esc(account?.name)} · ${esc(account?.label)}</p>${t.archiveReason?`<p class="statement-coverage">Consulta histórica: ${esc(t.archiveReason)}.</p>`:''}<div class="bigamount ${t.amount<0?'outgoing':'incoming'}">${money(t.amount)}</div><p>${esc((t.details||[]).join(' · '))}</p><dl class="info-grid"><div><dt>Documento bancário</dt><dd>${esc(t.bankDocument||'Não informado')}</dd></div><div><dt>Ordem no extrato da conta</dt><dd>${t.sourceSequence||'—'}</dd></div><div><dt>Saldo antes do lançamento</dt><dd>${money(t.balance-t.amount)}</dd></div><div><dt>Saldo após o lançamento</dt><dd>${money(t.balance)}</dd></div><div><dt>Base do saldo</dt><dd>${t.balanceBasis==='consolidated'?'Extrato consolidado com aplicação automática':'Conta corrente'}</dd></div><div><dt>Origem do saldo</dt><dd>${esc(t.balanceEvidence||'Calculado')}</dd></div>${t.fitid?`<div><dt>Identificador no OFX (FITID)</dt><dd>${esc(t.fitid)}</dd></div>`:''}</dl>${t.movementType==='investment-transfer'?`<div class="callout">${icon('info')}<span>Aplicação ou resgate automático. Não classificado como receita ou despesa operacional.</span></div>`:''}<div class="drawer-section"><h3>Documento de origem</h3>${doc?btn(ofx?'Ver registro '+t.sourceRecord+' no OFX':'Ver página '+t.sourcePage+' do extrato',`data-statement-source="${esc(t.id)}"`,'primary','file'):'<p class="annotation">Sem arquivo de origem.</p>'}${t.sourceFirstPage&&t.sourceFirstPage!==t.sourcePage?`<p class="annotation">A descrição começa na página ${t.sourceFirstPage} e continua na página ${t.sourcePage}.</p>`:''}${(t.additionalSources||[]).map(source=>btn('PDF anterior · página '+source.page,`data-statement-document="${esc(source.document)}" data-source-page="${source.page}"`,'','file')).join('')}</div><div class="drawer-section"><h3>Correspondência no sistema</h3>${o?link(o.title,'obligation',o.id,o.party,'wallet'):'<p class="annotation">Obrigação, ativo, contrato e comprovante ainda não vinculados. O extrato confirma a movimentação bancária; ele não identifica sozinho a composição contábil.</p>'}</div><p class="audit-note">A conferência de saldo foi concluída na importação. A conciliação documental continua pendente.</p>`};
  }
  function document(d){
    if(d.format==='ofx'){
      const rows=a.scope('transactions').filter(t=>t.sourceDocument===d.id).sort((x,y)=>x.sourceRecord-y.sourceRecord),selected=rows.find(t=>t.sourceRecord===a.current?.record);
      return {heading:'Extrato OFX original',wide:true,body:`<h2>${esc(d.name)}</h2><p class="description">${fullDate(d.period.start)} a ${fullDate(d.period.end)} · ${rows.length} registros · original preservado</p>${selected?`<div class="callout">${icon('file')}<span><b>Registro ${selected.sourceRecord} · ${fullDate(selected.date)} · ${money(selected.amount)}</b><br>${esc(selected.description)}<br>FITID: ${esc(selected.fitid)}</span></div>`:''}<div class="table-wrap"><table><thead><tr><th>Registro</th><th>Data</th><th>Histórico / FITID</th><th class="money">Valor</th></tr></thead><tbody>${rows.map(t=>`<tr ${t===selected?'class="statement-selected" aria-selected="true"':''}><td>${t.sourceRecord}</td><td>${fullDate(t.date)}</td><td><button class="textbtn" data-open="transaction" data-id="${esc(t.id)}">${esc(t.description)}</button><small>FITID ${esc(t.fitid)}</small></td><td class="money">${money(t.amount)}</td></tr>`).join('')}</tbody></table></div><p><a class="btn" href="${esc(d.originalUrl)}" download="${esc(d.name)}">Baixar OFX original</a></p><details><summary>Conteúdo original do OFX</summary><pre class="statement-text">${esc(d.pages[0].lines.join('\n'))}</pre></details><p class="audit-note">O OFX contém os movimentos bancários. Seu saldo datado da exportação não foi usado como uma posição histórica de investimentos.</p>`};
    }
    const index=Math.max(0,Math.min(d.pages.length-1,a.current?.page||0)),p=d.pages[index];
    return {heading:'Extrato original',wide:true,body:`<h2>${esc(d.name)}</h2><p class="description">${fullDate(d.period.start)} a ${fullDate(d.period.end)} · ${d.pages.length} página(s) · original preservado</p><div class="page-controls"><button data-doc-page="${Math.max(0,index-1)}" ${index===0?'disabled':''} aria-label="Página anterior">${icon('back')}</button><span>Página ${index+1} de ${d.pages.length}</span><button data-doc-page="${Math.min(d.pages.length-1,index+1)}" ${index===d.pages.length-1?'disabled':''} aria-label="Próxima página">${icon('chevron')}</button></div><iframe class="statement-pdf" title="${esc(d.name)} · página ${index+1}" src="${esc(d.originalUrl)}#page=${index+1}"></iframe><p><a class="btn" href="${esc(d.originalUrl)}#page=${index+1}" target="_blank" rel="noopener">Abrir PDF original</a></p><details><summary>Texto extraído desta página</summary><pre class="statement-text">${esc(p.lines.join('\n'))}</pre></details><p class="audit-note">O PDF pode conter seções fora do período importado. Consulte “Sobre a importação” para verificar o que compõe os totais.</p>`};
  }
  function dialog(kind,id){if(kind==='statement-import')return summary();if(kind==='transaction')return transaction(id);const d=a.scope('documents').find(x=>x.id===id);if((kind==='document'||kind==='process')&&d?.originalUrl)return document(d);return null;}
  function click(ds){if(ds.statementDocument){a.open('document',ds.statementDocument);a.current.page=Number(ds.sourcePage)-1;a.draw();return true;}if(ds.statementSource){const t=findTransaction(ds.statementSource);if(t?.sourceDocument){a.open('document',t.sourceDocument);a.current.page=(t.sourcePage||1)-1;a.current.record=t.sourceRecord;a.draw();}return true;}return false;}
  return {dialog,click};
}
